  snapshots=sorted(set([0,len(key)-1]+changes.tolist()+[int(key.argmin())]));rows.append(dict(role=r['role'],seed=r['seed'],near_goal_recomputed_mismatches=int(np.sum((key<=tol)!=near)),complete_recomputed_mismatches=int(np.sum(result!=complete)),retract_condition_recomputed_mismatches=int(np.sum(expected!=rs)),retract_tolerance_mm=1000*limit,success_steps=cfg['termination']['success_steps'],consecutive=cfg['termination']['force_consecutive_near_goal_steps'],goal_changes=events,snapshots=[dict(tick=k,keypoints_mm=float(1000*key[k]),near=bool(near[k]),accumulated_near_steps=int(n['near_goal_steps_after_goal_reset'][k]),subgoals=int(sub[k]),retract_phase=bool(rp[k]),retract_succeeded=bool(rs[k]),mean_fingertip_mm=float(1000*mean[k]),object_z_m=float(a['object_pose_w'][k,2])) for k in snapshots]))
